widget.solution:
def has_loop(fallback, start):
    slow = fast = start
    while fast is not None and fallback.get(fast) is not None:
        slow = fallback.get(slow)
        fast = fallback.get(fallback.get(fast))
        if fast is not None and slow == fast:
            return True
    return False
